/// P10: random operation sequences.
#[test]
fn state_machine_never_sends_without_confirmation_and_never_twice() {
    let mut total_sends = 0u64;
    check("command_state_machine", 500, |r| {
        let mut w = World::new();
        let audit = MemoryAudit::new();
        let mut svc = service(&w, &audit);
        let targets = [
            target("sim-vfd.json", &sim_link("sim"), 2),
            target("sim-temp-controller.json", &sim_link("sim"), 3),
            target("sim-vfd.json", &rtu_link("bus1"), 2),
        ];
        let roles = [Role::Viewer, Role::Operator, Role::Commissioner];
        // Model: the preview id that is currently confirmed and not yet executed.
        let mut confirmed: Option<u64> = None;
        let mut previewed: Option<u64> = None;
        let mut expected_sends = 0u64;
        for _ in 0..r.range_u64(5, 40) {
            let before = w.write_frames().len();
            // 60 %: the legal next step (so the send path is exercised); 40 %: anything.
            let op = if r.chance(600) {
                match svc.state() {
                    CommandState::Idle | CommandState::Done | CommandState::Failed if svc.armed_device().is_none() => 0,
                    CommandState::Armed | CommandState::Done | CommandState::Failed => 2,
                    CommandState::Previewed => 4,
                    _ => 5,
                }
            } else {
                r.below(9)
            };
            let good_role = op == 0 && r.chance(700);
            match op {
                0 => {
                    let t = if good_role {
                        targets[r.below(2) as usize].clone()
                    } else {
                        r.pick(&targets).unwrap().clone()
                    };
                    let role = if good_role {
                        Role::Commissioner
                    } else {
                        *r.pick(&roles).unwrap()
                    };
                    let ok = svc.arm(t, Operator { user: "u".into(), role }).is_ok();
                    if ok || svc.armed_device().is_none() {
                        confirmed = None;
                        previewed = None;
                    }
                }
                1 => {
                    svc.disarm(DisarmReason::Operator);
                    confirmed = None;
                    previewed = None;
                }
                2 | 3 => {
                    let pick = match svc.armed_unit() {
                        Some(2) if r.chance(700) => {
                            if r.chance(700) {
                                0
                            } else {
                                2
                            }
                        }
                        Some(3) if r.chance(700) => 1,
                        _ => r.below(4),
                    };
                    let (reg, v) = match pick.min(3) {
                        0 => ("freq_setpoint", r.range_u64(0, 6000) as f64 / 100.0),
                        1 => ("sp", r.range_u64(0, 1300) as f64 / 10.0),
                        2 => ("control_word", r.range_u64(0, 5) as f64),
                        _ => ("ramp_time", r.unit_f64() * 70.0),
                    };
                    match svc.preview(&mut w.link(), set(reg, v)) {
                        Ok(p) => {
                            previewed = Some(p.id);
                            assert!(confirmed.is_none());
                        }
                        Err(CommandError::WrongState { .. }) => {}
                        Err(_) => {
                            if svc.state() == CommandState::Idle {
                                previewed = None;
                                confirmed = None;
                            }
                        }
                    }
                }
                4 => {
                    let id = if r.chance(800) {
                        previewed.unwrap_or(0)
                    } else {
                        r.below(50)
                    };
                    if svc.confirm(id).is_ok() {
                        assert_eq!(Some(id), previewed, "only the current preview can be confirmed");
                        confirmed = previewed.take();
                    } else if svc.state() == CommandState::Idle {
                        previewed = None;
                    }
                }
                5 | 6 => {
                    let res = svc.execute(&mut w.link());
                    let sent = w.write_frames().len() - before;
                    match res {
                        Ok(o) => {
                            assert_eq!(Some(o.preview_id), confirmed, "execute only runs a confirmed preview");
                            assert_eq!(sent, 1);
                            expected_sends += 1;
                        }
                        Err(_) => assert_eq!(sent, 0),
                    }
                    confirmed = None;
                    // execute() in the Previewed state is refused and keeps the preview.
                    if svc.state() != CommandState::Previewed {
                        previewed = None;
                    }
                }
                7 => {
                    let _ = svc.cancel();
                    confirmed = None;
                    previewed = None;
                }
                _ => {
                    w.clock.advance(if r.chance(200) {
                        r.range_u64(50_000, 70_000)
                    } else {
                        r.range_u64(0, 5_000)
                    });
                    audit.set_failing(r.chance(150));
                }
            }
            if !matches!(op, 5 | 6) {
                assert_eq!(w.write_frames().len(), before, "only execute writes");
            }
        }
        audit.set_failing(false);
        let frames = w.write_frames();
        assert_eq!(frames.len() as u64, expected_sends);
        assert_eq!(svc.sends(), expected_sends);
        let recs = audit.records();
        let sent_records = recs.iter().filter(|x| x.event == Some(AuditEvent::Sent)).count() as u64;
        assert_eq!(sent_records, expected_sends, "every send has its 'sent' record");
        for f in &frames {
            assert_ne!(f[0], 0, "never broadcast");
            let (_, pdu) = rtu::decode_adu(f).unwrap();
            match WriteRequest::decode(pdu).unwrap() {
                WriteRequest::SingleRegister { address: 1, value } if f[0] == 2 => {
                    assert!(value <= 5000, "VFD setpoint in bounds")
                }
                WriteRequest::SingleRegister { address: 0, value } if f[0] == 2 => assert!([0, 1, 4].contains(&value)),
                WriteRequest::SingleRegister { address: 2, value } if f[0] == 2 => assert!((1..=600).contains(&value)),
                WriteRequest::SingleRegister { address: 1, value } if f[0] == 3 => assert!(value <= 1200),
                other => panic!("unexpected write {other:?} to unit {}", f[0]),
            }
        }
        total_sends += expected_sends;
    });
    eprintln!("command_state_machine: {total_sends} frames sent across all cases");
    assert!(
        total_sends > 500,
        "the generator reaches the send path ({total_sends} sends)"
    );
}

/// C1: once the arm has expired, nothing previewed or confirmed before can be sent,
/// and a fresh arm is needed (random idle gaps around the 60 s limit).
#[test]
fn c1_expired_arm_never_sends() {
    check("command_expired_arm", 300, |r| {
        let mut w = World::new();
        let audit = MemoryAudit::new();
        let mut svc = service(&w, &audit);
        svc.arm(target("sim-vfd.json", &sim_link("sim"), 2), op(Role::Operator))
            .unwrap();
        let gap1 = r.range_u64(0, 70_000);
        w.clock.advance(gap1);
        let previewed = svc.preview(&mut w.link(), set("freq_setpoint", 12.0));
        assert_eq!(previewed.is_ok(), gap1 < 60_000, "preview after {gap1} ms idle");
        let Ok(p) = previewed else {
            assert_eq!(svc.armed_device(), None);
            assert!(w.write_frames().is_empty());
            return;
        };
        let gap2 = r.range_u64(0, 70_000);
        w.clock.advance(gap2);
        let confirmed = svc.confirm(p.id);
        assert_eq!(confirmed.is_ok(), gap2 < 60_000);
        let gap3 = r.range_u64(0, 70_000);
        w.clock.advance(gap3);
        let res = svc.execute(&mut w.link());
        let should_send = gap2 < 60_000 && gap3 < 60_000;
        assert_eq!(res.is_ok(), should_send, "gaps {gap1}/{gap2}/{gap3}");
        assert_eq!(w.write_frames().len(), usize::from(should_send));
        // Never twice for one confirmation.
        assert!(svc.execute(&mut w.link()).is_err());
        assert_eq!(w.write_frames().len(), usize::from(should_send));
    });
}

/// C2: for every writable register of the simulated profiles, a random value is
/// accepted exactly when it lies inside the profile bounds, and what is sent decodes inside them.
#[test]
fn c2_bounds_always_enforced() {
    check("command_bounds", 400, |r| {
        let mut w = World::new();
        let audit = MemoryAudit::new();
        let mut svc = service(&w, &audit);
        let (file, unit) = *r
            .pick(&[("sim-vfd.json", 2u8), ("sim-temp-controller.json", 3u8)])
            .unwrap();
        let t = target(file, &sim_link("sim"), unit);
        let profile = t.profile.clone();
        svc.arm(t, op(Role::Commissioner)).unwrap();
        let regs: Vec<_> = profile
            .registers
            .iter()
            .filter(|reg| reg.write.is_some() && !reg.id.starts_with("comm_"))
            .collect();
        let reg = *r.pick(&regs).unwrap();
        let wspec = reg.write.clone().unwrap();
        let v = match r.below(3) {
            0 => r.range_u64(0, 2000) as f64 / 10.0 - 20.0,
            1 => r.range_u64(0, 300) as f64,
            _ => wspec
                .allowed_values
                .as_ref()
                .and_then(|a| r.pick(a).copied())
                .unwrap_or(1.0),
        };
        let inside = if let Some(a) = &wspec.allowed_values {
            a.contains(&v)
        } else {
            let (min, max) = (wspec.min.unwrap(), wspec.max.unwrap());
            let step_ok = wspec.step.is_none_or(|s| {
                let k = (v - min) / s;
                (k - k.round()).abs() <= 1e-6
            });
            let range_ok = reg.valid_range.is_none_or(|[lo, hi]| v >= lo && v <= hi);
            v >= min && v <= max && step_ok && range_ok
        };
        let res = svc.preview(&mut w.link(), set(&reg.id, v));
        assert_eq!(res.is_ok(), inside, "{}={v}: {res:?}", reg.id);
        if let Ok(p) = res {
            svc.confirm(p.id).unwrap();
            svc.execute(&mut w.link()).unwrap();
            let frames = w.write_frames();
            let (_, pdu) = rtu::decode_adu(frames.last().unwrap()).unwrap();
            let WriteRequest::SingleRegister { value, .. } = WriteRequest::decode(pdu).unwrap() else {
                panic!("single register expected");
            };
            let eng = f64::from(if reg.type_name == buslink_core::codec::TypeName::I16 {
                value as i16 as i32
            } else {
                i32::from(value)
            }) * reg.scale.unwrap_or(1.0);
            assert!((eng - v).abs() < 1e-6, "sent {eng}, asked {v}");
        } else {
            assert!(w.write_frames().is_empty());
        }
    });
}

/// C3: comm-config requests follow the wizard rules.
#[test]
fn c3_comm_config_rules() {
    let mut w = World::new();
    let audit = MemoryAudit::new();
    let mut svc = service(&w, &audit);
    let t = target("sim-vfd.json", &sim_link("sim"), 2);
    let cc = |setting, value| CommandRequest::CommConfig { setting, value };
    svc.arm(t.clone(), op(Role::Operator)).unwrap();
    assert!(matches!(
        svc.preview(&mut w.link(), cc(CommSettingKind::UnitId, 5)),
        Err(CommandError::Role {
            need: "commissioner",
            ..
        })
    ));
    svc.arm(t.clone(), op(Role::Commissioner)).unwrap();
    // Outside the wizard path the comm registers are refused, even for a commissioner.
    assert!(matches!(
        svc.preview(&mut w.link(), set("comm_unit_id", 5.0)),
        Err(CommandError::ControlNotAllowed(_))
    ));
    assert!(matches!(
        svc.preview(&mut w.link(), cc(CommSettingKind::UnitId, 0)),
        Err(CommandError::BroadcastRejected)
    ));
    assert!(matches!(
        svc.preview(&mut w.link(), cc(CommSettingKind::UnitId, 248)),
        Err(CommandError::OutOfBounds(_))
    ));
    assert!(matches!(
        svc.preview(&mut w.link(), cc(CommSettingKind::Baud, 115_200)),
        Err(CommandError::OutOfBounds(_))
    ));
    assert!(w.write_frames().is_empty());
    // Baud 19200 is code 2; read-back is deferred to the reconnect.
    let p = svc.preview(&mut w.link(), cc(CommSettingKind::Baud, 19_200)).unwrap();
    assert_eq!(p.raw_registers, vec![2]);
    assert_eq!(p.address, 8);
    let change = p.comm_change.clone().unwrap();
    assert_eq!(
        (change.setting, change.value, change.apply),
        (CommSettingKind::Baud, 19_200, Apply::Immediate)
    );
    svc.confirm(p.id).unwrap();
    let o = svc.execute(&mut w.link()).unwrap();
    assert_eq!((o.ack, o.readback), (Ack::Acknowledged, Readback::Unknown));
    assert!(o.readback_error.unwrap().contains("after reconnect"));
    assert_eq!(w.write_frames().len(), 1);
    // A profile without comm_config: the soil sensor documents none.
    let soil = target("bgt-smps-8in1.json", &sim_link("sim"), 2);
    if svc.arm(soil, op(Role::Commissioner)).is_ok() {
        assert!(svc.preview(&mut w.link(), cc(CommSettingKind::UnitId, 5)).is_err());
    }
    assert_eq!(w.write_frames().len(), 1);
}

// ---- security review 07, M1: the role is host state, not an IPC claim ----

#[test]
fn forged_role_in_the_arm_request_is_rejected() {
