//! Test-only TLS client that trusts exactly one certificate fingerprint, a tiny
//! HTTP/1.1 requester and a WebSocket connector for the LAN server tests.
#![allow(
    dead_code,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::type_complexity
